package com.mirutina.diaria;
import android.app.*;import android.content.*;import android.os.Build;
public class AlarmReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){String title=i.getStringExtra("title");if(title==null)return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel("rutina","Recordatorios",NotificationManager.IMPORTANCE_HIGH));PendingIntent pi=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"rutina"):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("Mi Rutina Diaria").setContentText("En 10 minutos: "+title).setContentIntent(pi).setAutoCancel(true);nm.notify(i.getIntExtra("id",0),b.build());Scheduler.schedule(c);}}
